      --color <COLOR>              Set color output mode [default: auto] [possible values: always, never, auto]
      --dump                       Force dumping operations into a file even in dry-run mode
      --dump-prefix <DUMP_PREFIX>  Set the dump file prefix [default: rnr-]
      --no-dump                    Do not dump operations into a file
  -u, --undo                       Undo the operations from the dump file
  -h, --help                       Print help
"""

TO_ASCII_HELP = """Replace file name UTF-8 chars with ASCII chars representation

Usage: executable to-ascii [OPTIONS] <PATH(S)>...

Arguments:
  <PATH(S)>...  Target paths

Options:
  -n, --dry-run                    Only show what would be done (default mode)
  -f, --force                      Make actual changes to files
  -b, --backup                     Generate file backups before renaming
  -s, --silent                     Do not print any information
      --color <COLOR>              Set color output mode [default: auto] [possible values: always, never, auto]
      --dump                       Force dumping operations into a file even in dry-run mode
      --dump-prefix <DUMP_PREFIX>  Set the dump file prefix [default: rnr-]
      --no-dump                    Do not dump operations into a file
  -D, --include-dirs               Rename matching directories
  -r, --recursive                  Recursive mode
  -d, --max-depth <LEVEL>          Set max depth in recursive mode
  -x, --hidden                     Include hidden files and directories
  -h, --help                       Print help
"""

# ANSI sequences used by the original's common output paths.
BOLD = "\033[1m"
RESET = "\033[0m"
GREY = "\033[38;5;8m"
GREEN = "\033[32m"
RED_BOLD = "\033[1;31m"

@dataclass
class Options:
    dry_run: bool = False
    force: bool = False
    backup: bool = False
    silent: bool = False
    color: str = "auto"
    dump: bool = False
    no_dump: bool = False
    dump_prefix: str = "rnr-"
    recursive: bool = False
    include_dirs: bool = False
    hidden: bool = False
    max_depth: Optional[int] = None
    replace_limit: int = 1
    replace_transform: Optional[str] = None
    undo: bool = False

    @property
    def is_dry(self) -> bool:
        return not self.force

    def use_color(self) -> bool:
        if self.color == "always":
            return True
        if self.color == "never":
            return False
        return sys.stdout.isatty()

    def should_dump(self) -> bool:
        if self.no_dump:
            return False
        if self.force:
            return True
        return self.dump

@dataclass
class Operation:
    source: str
    target: str
    is_dir: bool = False
    # Target rendering as (text, changed?) chunks for --color=always.
    segments: List[Tuple[str, bool]] = field(default_factory=list)


def stdout_write(s: str):
    sys.stdout.write(s)


def stderr_write(s: str):
    sys.stderr.write(s)


def print_help(help_text: str, to_stderr: bool = False, code: int = 0) -> int:
    (stderr_write if to_stderr else stdout_write)(help_text)
    return code


def cli_error(message: str, usage: Optional[str] = None, tip: Optional[str] = None) -> int:
    stderr_write(f"error: {message}\n\n")
    if tip:
        stderr_write(f"  tip: {tip}\n\n")
    if usage:
        stderr_write(f"Usage: {usage}\n\n")
    stderr_write("For more information, try '--help'.\n")
    return 2


def similar_tip(cmd: str) -> Optional[str]:
    table = {"Regex": "regex", "to_ascii": "to-ascii", "fromfile": "from-file"}
    if cmd in table:
        return f"a similar subcommand exists: '{table[cmd]}'"
    # Tiny edit-distance-ish hints for common punctuation/case variants.
    low = cmd.lower().replace("_", "-")
    for known in ("regex", "from-file", "to-ascii"):
        if low == known or low.replace("-", "") == known.replace("-", ""):
            return f"a similar subcommand exists: '{known}'"
    return None


def top_unrecognized(token: str) -> int:
    if token.startswith('-'):
        return cli_error(f"unexpected argument '{token}' found", "executable <COMMAND>")
    tip = similar_tip(token)
    if tip:
        return cli_error(f"unrecognized subcommand '{token}'", "executable <COMMAND>", tip)
    return cli_error(f"unrecognized subcommand '{token}'", "executable <COMMAND>")


def value_required(opt_display: str) -> int:
    return cli_error(f"a value is required for '{opt_display}' but none was supplied")


def invalid_value(value: str, opt: str, possible: Optional[List[str]] = None, reason: Optional[str] = None) -> int:
    stderr_write(f"error: invalid value '{value}' for '{opt}'")
    if reason:
        stderr_write(f": {reason}")
    stderr_write("\n")
    if possible:
        stderr_write(f"  [possible values: {', '.join(possible)}]\n")
    stderr_write("\nFor more information, try '--help'.\n")
    return 2


def usage_for(cmd: str, opts: Options, err_kind: str = "generic") -> str:
    if cmd == "regex":
        return "executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>..." if err_kind == "with_options" else "executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>..."
    if cmd == "to-ascii":
        return "executable to-ascii [OPTIONS] <PATH(S)>..." if err_kind == "with_options" else "executable to-ascii <PATH(S)>..."
    if cmd == "from-file":
        return "executable from-file [OPTIONS] <DUMPFILE>"
    return "executable <COMMAND>"


def dependency_error(cmd: str, opts: Options, dep: str) -> int:
    # Clap reports this as a missing required --recursive argument and shows
    # a context-specific usage. Reconstruct the common forms.
    bits = ["executable", cmd, "--recursive"]
    if opts.include_dirs:
        bits.append("--include-dirs")
    if dep == "max-depth":
        bits.append("--max-depth <LEVEL>")
    elif opts.max_depth is not None:
        bits.append("--max-depth <LEVEL>")
    if opts.hidden:
        bits.append("--hidden")
    if opts.color != "auto":
        bits.append("--color <COLOR>")
    # The original often includes --color in the dependency usage when it was
    # supplied. This approximation is enough for normal CLI use.
    if cmd == "regex":
        bits += ["<EXPRESSION>", "<REPLACEMENT>", "<PATH(S)>..."]
    elif cmd == "to-ascii":
        bits += ["<PATH(S)>..."]
    usage = " ".join(bits)
    stderr_write("error: the following required arguments were not provided:\n  --recursive\n\n")
    stderr_write(f"Usage: {usage}\n\nFor more information, try '--help'.\n")
    return 2


def set_flag(opts: Options, longname: str, display: str, cmd: str) -> Optional[int]:
    if longname == "dry_run":
        if opts.force:
            stderr_write("error: the argument '--force' cannot be used with '--dry-run'\n\n")
            stderr_write(f"Usage: executable {cmd} --force ")
            if cmd == "regex": stderr_write("<EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\n")
            elif cmd == "to-ascii": stderr_write("<PATH(S)>...\n\n")
            else: stderr_write("<DUMPFILE>\n\n")
            stderr_write("For more information, try '--help'.\n")
            return 2
        opts.dry_run = True
    elif longname == "force":
        if opts.dry_run:
            stderr_write("error: the argument '--dry-run' cannot be used with '--force'\n\n")
            stderr_write(f"Usage: executable {cmd} --dry-run ")
            if cmd == "regex": stderr_write("<EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\n")
            elif cmd == "to-ascii": stderr_write("<PATH(S)>...\n\n")
            else: stderr_write("<DUMPFILE>\n\n")
            stderr_write("For more information, try '--help'.\n")
            return 2
        opts.force = True
    elif longname == "dump":
        if opts.no_dump:
            stderr_write("error: the argument '--no-dump' cannot be used with '--dump'\n\n")
            stderr_write(f"Usage: executable {cmd} --no-dump ")
            if cmd == "regex": stderr_write("<EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\n")
            elif cmd == "to-ascii": stderr_write("<PATH(S)>...\n\n")
            else: stderr_write("<DUMPFILE>\n\n")
            stderr_write("For more information, try '--help'.\n")
            return 2
        opts.dump = True
    elif longname == "no_dump":
        if opts.dump:
            stderr_write("error: the argument '--dump' cannot be used with '--no-dump'\n\n")
            stderr_write(f"Usage: executable {cmd} --dump ")
            if cmd == "regex": stderr_write("<EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\n")
            elif cmd == "to-ascii": stderr_write("<PATH(S)>...\n\n")
            else: stderr_write("<DUMPFILE>\n\n")
            stderr_write("For more information, try '--help'.\n")
            return 2
        opts.no_dump = True
    else:
        setattr(opts, longname, True)
    return None


def parse_u64(value: str, opt_display: str) -> Tuple[Optional[int], Optional[int]]:
    # The original is a Rust usize parser: only decimal digits are accepted.
    if not value.isdigit():
        return None, invalid_value(value, opt_display, reason="invalid digit found in string")
    try:
        return int(value), None
    except Exception:
        return None, invalid_value(value, opt_display, reason="number too large to fit in target type")


def parse_common(cmd: str, argv: List[str], allowed_extra: str) -> Tuple[Optional[Options], Optional[List[str]], int]:
    opts = Options()
    pos: List[str] = []
    i = 0
    after_dd = False
    help_text = {"regex": REGEX_HELP, "from-file": FROM_FILE_HELP, "to-ascii": TO_ASCII_HELP}[cmd]

    long_value_opts = {
        "--color": ("color", "--color <COLOR>"),
        "--dump-prefix": ("dump_prefix", "--dump-prefix <DUMP_PREFIX>"),
    }
    if cmd == "regex":
        long_value_opts.update({
            "--replace-limit": ("replace_limit", "--replace-limit <LIMIT>"),
            "--replace-transform": ("replace_transform", "--replace-transform <REPLACE_TRANSFORM>"),
            "--max-depth": ("max_depth", "--max-depth <LEVEL>"),
        })
    elif cmd == "to-ascii":
        long_value_opts.update({"--max-depth": ("max_depth", "--max-depth <LEVEL>")})

    long_flags = {
        "--dry-run": "dry_run",
        "--force": "force",
        "--backup": "backup",
        "--silent": "silent",
        "--dump": "dump",
        "--no-dump": "no_dump",
    }
    if cmd in ("regex", "to-ascii"):
        long_flags.update({"--include-dirs": "include_dirs", "--recursive": "recursive", "--hidden": "hidden"})
    if cmd == "from-file":
        long_flags.update({"--undo": "undo"})

    short_flags = {"n": "dry_run", "f": "force", "b": "backup", "s": "silent"}
    if cmd in ("regex", "to-ascii"):
        short_flags.update({"D": "include_dirs", "r": "recursive", "x": "hidden"})
    if cmd == "from-file":
        short_flags.update({"u": "undo"})
    short_values: Dict[str, Tuple[str, str]] = {}
    if cmd == "regex":
        short_values = {"l": ("replace_limit", "--replace-limit <LIMIT>"), "t": ("replace_transform", "--replace-transform <REPLACE_TRANSFORM>"), "d": ("max_depth", "--max-depth <LEVEL>")}
    elif cmd == "to-ascii":
        short_values = {"d": ("max_depth", "--max-depth <LEVEL>")}

    while i < len(argv):
        tok = argv[i]
        if not after_dd and tok in ("-h", "--help"):
            stdout_write(help_text)
            return None, None, 0
        if not after_dd and tok == "--":
            after_dd = True
            i += 1
            continue
        if not after_dd and tok.startswith("--") and tok != "--":
            name, eq, eqval = tok.partition("=")
            if name in long_flags:
                if eq:
                    return None, None, cli_error(f"unexpected value '{eqval}' for '{name}'", usage_for(cmd, opts))
                rc = set_flag(opts, long_flags[name], name, cmd)
                if rc is not None:
                    return None, None, rc
                i += 1
                continue
            if name in long_value_opts:
                attr, display = long_value_opts[name]
                if eq:
                    val = eqval
                else:
                    if i + 1 >= len(argv):
                        return None, None, value_required(display.split()[0] if display.startswith("--") else display)
                    val = argv[i+1]
                    # clap generally treats a following --flag as no value.
                    if val.startswith('-'):
                        return None, None, value_required(display.split()[0] if display.startswith("--") else display)
                    i += 1
                rc = assign_option_value(opts, attr, val, display)
                if rc is not None:
                    return None, None, rc
                i += 1
                continue
            # Unknown option.
            tip = f"to pass '{tok}' as a value, use '-- {tok}'" if tok.startswith('--') else None
            return None, None, cli_error(f"unexpected argument '{tok}' found", usage_for(cmd, opts), tip)
        if not after_dd and tok.startswith('-') and tok != "-":
            # Short flag cluster, with possible attached value for -l/-t/-d.
            j = 1
            while j < len(tok):
                ch = tok[j]
                if ch in short_flags:
                    rc = set_flag(opts, short_flags[ch], '-' + ch, cmd)
                    if rc is not None:
                        return None, None, rc
                    j += 1
                    continue
                if ch in short_values:
                    attr, display = short_values[ch]
                    if j + 1 < len(tok):
                        val = tok[j+1:]
                        j = len(tok)
                    else:
                        if i + 1 >= len(argv):
                            return None, None, value_required(display.split()[0])
                        val = argv[i+1]
                        if val.startswith('-'):
                            # Close to clap's behavior for negative-looking values.
                            return None, None, cli_error(f"unexpected argument '{val}' found", usage_for(cmd, opts, "with_options"), f"to pass '{val}' as a value, use '-- {val}'")
                        i += 1
                        j = len(tok)
                    rc = assign_option_value(opts, attr, val, display)
                    if rc is not None:
                        return None, None, rc
                    continue
                return None, None, cli_error(f"unexpected argument '-{ch}' found", usage_for(cmd, opts, "with_options"), f"to pass '-{ch}' as a value, use '-- -{ch}'")
            i += 1
            continue
        pos.append(tok)
        i += 1

    # Option dependencies.
    if cmd in ("regex", "to-ascii"):
        if opts.hidden and not opts.recursive:
            return None, None, dependency_error(cmd, opts, "hidden")
        if opts.max_depth is not None and not opts.recursive:
            return None, None, dependency_error(cmd, opts, "max-depth")
    return opts, pos, -1


def assign_option_value(opts: Options, attr: str, val: str, display: str) -> Optional[int]:
    if attr == "color":
        if val not in ("always", "never", "auto"):
            return invalid_value(val, "--color <COLOR>", ["always", "never", "auto"])
        opts.color = val
    elif attr == "replace_transform":
        if val not in ("upper", "lower", "ascii"):
            return invalid_value(val, "--replace-transform <REPLACE_TRANSFORM>", ["upper", "lower", "ascii"])
        opts.replace_transform = val
    elif attr == "replace_limit":
        n, rc = parse_u64(val, "--replace-limit <LIMIT>")
        if rc is not None:
            return rc
        opts.replace_limit = n if n is not None else 1
    elif attr == "max_depth":
        n, rc = parse_u64(val, "--max-depth <LEVEL>")
        if rc is not None:
            return rc
        opts.max_depth = n
    elif attr == "dump_prefix":
        opts.dump_prefix = val
    else:
        setattr(opts, attr, val)
    return None


def validate_positionals(cmd: str, pos: List[str]) -> Optional[int]:
    if cmd == "regex":
        if len(pos) == 0:
            stderr_write(REGEX_HELP)
            return 2
        missing = []
        if len(pos) < 2:
            missing.append("<REPLACEMENT>")
        if len(pos) < 3:
            missing.append("<PATH(S)>...")
        if missing:
            stderr_write("error: the following required arguments were not provided:\n")
            for m in missing:
                stderr_write(f"  {m}\n")
            stderr_write("\nUsage: executable regex <EXPRESSION> <REPLACEMENT> <PATH(S)>...\n\nFor more information, try '--help'.\n")
            return 2
    elif cmd == "to-ascii":
        if len(pos) == 0:
            stderr_write(TO_ASCII_HELP)
            return 2
    elif cmd == "from-file":
        if len(pos) == 0:
            stderr_write(FROM_FILE_HELP)
            return 2
        if len(pos) > 1:
            return cli_error(f"unexpected argument '{pos[1]}' found", "executable from-file [OPTIONS] <DUMPFILE>")
    return None

