def to_ascii_text(text: str) -> str:
    out: List[str] = []
    for ch in text:
        if ord(ch) < 128:
            out.append(ch)
            continue
        if ch in CUSTOM_TRANSLIT:
            out.append(CUSTOM_TRANSLIT[ch])
            continue
        decomposed = unicodedata.normalize('NFKD', ch)
        encoded = decomposed.encode('ascii', 'ignore').decode('ascii')
        if encoded:
            out.append(encoded)
            continue
        # Drop remaining non-ASCII control/symbol characters.
    return ''.join(out)


def transform_replacement(s: str, transform: Optional[str]) -> str:
    if transform == "upper":
        return s.upper()
    if transform == "lower":
        return s.lower()
    if transform == "ascii":
        return to_ascii_text(s)
    return s


def normalize_regex_pattern(expr: str) -> str:
    # Rust regex accepts (?<name>...) while Python's re wants (?P<name>...).
    return re.sub(r"\(\?<([A-Za-z_][A-Za-z0-9_]*)>", r"(?P<\1>", expr)


def rust_group(match: re.Match, name: str) -> str:
    try:
        if name.isdigit():
            idx = int(name)
            if idx <= (match.lastindex or 0) or idx == 0:
                val = match.group(idx)
                return val if val is not None else ""
            return ""
        if name in match.re.groupindex:
            val = match.group(name)
            return val if val is not None else ""
        return ""
    except Exception:
        return ""


def expand_replacement(repl: str, match: re.Match) -> str:
    res: List[str] = []
    i = 0
    n = len(repl)
    while i < n:
        ch = repl[i]
        if ch != '$':
            res.append(ch)
            i += 1
            continue
        if i + 1 >= n:
            res.append('$')
            i += 1
            continue
        nxt = repl[i+1]
        if nxt == '$':
            res.append('$')
            i += 2
            continue
        if nxt == '{':
            end = repl.find('}', i+2)
            if end == -1:
                res.append('$')
                i += 1
                continue
            name = repl[i+2:end]
            res.append(rust_group(match, name))
            i = end + 1
            continue
        if nxt.isalnum() or nxt == '_':
            j = i + 1
            while j < n and (repl[j].isalnum() or repl[j] == '_'):
                j += 1
            name = repl[i+1:j]
            res.append(rust_group(match, name))
            i = j
            continue
        res.append('$')
        i += 1
    return ''.join(res)


def replace_basename(regex: re.Pattern, replacement: str, basename: str, limit: int, transform: Optional[str]) -> Tuple[str, List[Tuple[str, bool]]]:
    count_limit = None if limit == 0 else limit
    pieces: List[str] = []
    segments: List[Tuple[str, bool]] = []
    last = 0
    count = 0
    for m in regex.finditer(basename):
        if count_limit is not None and count >= count_limit:
            break
        # Python finditer handles empty matches the same way re.sub does.
        if m.start() < last:
            continue
        unchanged = basename[last:m.start()]
        if unchanged:
            pieces.append(unchanged)
            segments.append((unchanged, False))
        rep = transform_replacement(expand_replacement(replacement, m), transform)
        if rep:
            pieces.append(rep)
            segments.append((rep, True))
        last = m.end()
        count += 1
    tail = basename[last:]
    if tail:
        pieces.append(tail)
        segments.append((tail, False))
    if count == 0:
        return basename, [(basename, False)] if basename else []
    return ''.join(pieces), segments


def strip_trailing_slashes(p: str) -> str:
    if p == "":
        return p
    # Preserve root-like paths.
    while len(p) > 1 and p.endswith(os.sep):
        p = p[:-1]
    return p


def dirname_basename(path: str) -> Tuple[str, str]:
    p = strip_trailing_slashes(path)
    return os.path.dirname(p), os.path.basename(p)


def join_display(dirname: str, basename: str) -> str:
    if dirname == "":
        return basename
    return os.path.join(dirname, basename)


def path_depth(root: str, path: str) -> int:
    root_norm = os.path.normpath(root)
    path_norm = os.path.normpath(path)
    if root_norm == path_norm:
        return 0
    try:
        rel = os.path.relpath(path_norm, root_norm)
    except ValueError:
        return 0
    if rel == ".":
        return 0
    return len([x for x in rel.split(os.sep) if x and x != "."])


def is_hidden_name(name: str) -> bool:
    return name.startswith('.') and name not in ('.', '..')


def candidate_is_dir(path: str) -> bool:
    try:
        return os.path.isdir(path)
    except OSError:
        return False


def lexists(path: str) -> bool:
    try:
        return os.path.lexists(path)
    except OSError:
        return False


def collect_candidates(paths: List[str], opts: Options) -> List[Tuple[str, bool]]:
    candidates: List[Tuple[str, bool]] = []
    seen = set()
    for raw in paths:
        root = strip_trailing_slashes(raw)
        if not lexists(root):
            continue
        isdir = candidate_is_dir(root)
        if not opts.recursive or not isdir:
            if isdir:
                if opts.include_dirs:
                    key = (root, True)
                    if key not in seen:
                        seen.add(key); candidates.append(key)
            else:
                key = (root, False)
                if key not in seen:
                    seen.add(key); candidates.append(key)
            continue
        # Recursive directory. Include children up to max_depth. Root itself is
        # a directory candidate only when requested.
        maxd = opts.max_depth
        if opts.include_dirs:
            key = (root, True)
            if key not in seen:
                seen.add(key); candidates.append(key)
        for cur, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
            cur_depth = path_depth(root, cur)
            # Filter hidden discovered entries unless requested. Explicit hidden
            # root is still walked; its children follow the same filtering rule.
            if not opts.hidden:
                dirnames[:] = [d for d in dirnames if not is_hidden_name(d)]
                filenames = [f for f in filenames if not is_hidden_name(f)]
            if maxd is not None and cur_depth >= maxd:
                dirnames[:] = []
                if cur_depth >= maxd:
                    filenames = []
            # Directory candidates (including symlink-to-dir entries, but not traversed by os.walk).
            if opts.include_dirs:
                for d in list(dirnames):
                    p = os.path.join(cur, d)
                    ddepth = path_depth(root, p)
                    if maxd is not None and ddepth > maxd:
                        continue
                    key = (p, True)
                    if key not in seen:
                        seen.add(key); candidates.append(key)
            for f in filenames:
                p = os.path.join(cur, f)
                fdepth = path_depth(root, p)
                if maxd is not None and fdepth > maxd:
                    continue
                # If it is a symlink to a directory, the original treats it as
                # a directory and only includes it with -D.
                if candidate_is_dir(p):
                    if opts.include_dirs:
                        key = (p, True)
                        if key not in seen:
                            seen.add(key); candidates.append(key)
                    continue
                key = (p, False)
                if key not in seen:
                    seen.add(key); candidates.append(key)
    # Rename deeper paths before parents. The original parallelizes same-depth
    # work, so this deterministic ordering preserves the important invariant.
    candidates.sort(key=lambda x: (x[0].count(os.sep), x[0]), reverse=True)
    return candidates


def segments_for_ascii(old: str, new: str) -> List[Tuple[str, bool]]:
    if old == new:
        return [(new, False)] if new else []
    # Longest common prefix/suffix on rendered strings.
    p = 0
    while p < len(old) and p < len(new) and old[p] == new[p]:
        p += 1
    s = 0
    while s < (len(old) - p) and s < (len(new) - p) and old[len(old)-1-s] == new[len(new)-1-s]:
        s += 1
    segs: List[Tuple[str, bool]] = []
    if p:
        segs.append((new[:p], False))
    mid_end = len(new) - s if s else len(new)
    if mid_end > p:
        segs.append((new[p:mid_end], True))
    if s:
        segs.append((new[len(new)-s:], False))
    return segs


def build_regex_operations(regex: re.Pattern, replacement: str, paths: List[str], opts: Options) -> List[Operation]:
    ops: List[Operation] = []
    for path, isdir in collect_candidates(paths, opts):
        d, b = dirname_basename(path)
        new_b, segs = replace_basename(regex, replacement, b, opts.replace_limit, opts.replace_transform)
        if new_b == b:
            continue
        target = join_display(d, new_b)
        ops.append(Operation(path, target, isdir, segs))
    return ops


def build_ascii_operations(paths: List[str], opts: Options) -> List[Operation]:
    ops: List[Operation] = []
    for path, isdir in collect_candidates(paths, opts):
        d, b = dirname_basename(path)
        new_b = to_ascii_text(b)
        if new_b == b:
            continue
        target = join_display(d, new_b)
        ops.append(Operation(path, target, isdir, segments_for_ascii(b, new_b)))
    return ops


def print_dry_run(opts: Options):
    if opts.silent or not opts.is_dry:
        return
    if opts.use_color():
        stdout_write(f"{BOLD}This is a DRY-RUN{RESET}\n")
    else:
        stdout_write("This is a DRY-RUN\n")


def split_dir_name_for_color(path: str) -> Tuple[str, str]:
    p = strip_trailing_slashes(path)
    d = os.path.dirname(p)
    b = os.path.basename(p)
    if d:
        prefix = d + os.sep
        return prefix, b
    return "", b


def colored_source(path: str) -> str:
    prefix, b = split_dir_name_for_color(path)
    if prefix:
        return f"{GREY}{prefix}{RESET}{GREY}{b}{RESET}"
    return f"{GREY}{path}{RESET}"


def colored_target(op: Operation) -> str:
    prefix, _ = split_dir_name_for_color(op.target)
    parts = []
    if prefix:
        parts.append(f"{GREEN}{prefix}{RESET}")
    if op.segments:
        for text, changed in op.segments:
            if not text:
                continue
            parts.append((RED_BOLD if changed else GREEN) + text + RESET)
    else:
        # Fallback: mark basename as changed.
        _, b = split_dir_name_for_color(op.target)
        if b:
            parts.append(f"{RED_BOLD}{b}{RESET}")
    return ''.join(parts)


def print_operation(op: Operation, opts: Options):
    if opts.silent:
        return
    if opts.use_color():
        stdout_write(f"{colored_source(op.source)} -> {colored_target(op)}\n")
    else:
        stdout_write(f"{op.source} -> {op.target}\n")


def print_backup(src: str, backup: str, opts: Options):
    if opts.silent:
        return
    if opts.use_color():
        stdout_write(f"{BOLD}Info: {RESET} Backup created - {GREY}{src} -> {backup}{RESET}\n")
    else:
        stdout_write(f"Info:  Backup created - {src} -> {backup}\n")


def backup_path(src: str) -> str:
    base = src + ".bk"
    if not lexists(base):
        return base
    i = 1
    while True:
        cand = base + f".{i}"
        if not lexists(cand):
            return cand
        i += 1


def maybe_backup(src: str, opts: Options):
    if not opts.backup:
        return
    # Original only backs up files (directories are just renamed).
    try:
        if os.path.isfile(src):
            dst = backup_path(src)
            shutil.copy2(src, dst)
            print_backup(src, dst, opts)
    except Exception:
        # If backup itself fails, surface it similarly to a rename failure.
        raise


def os_error_text(exc: BaseException) -> str:
    if isinstance(exc, OSError) and exc.errno:
        return f"{os.strerror(exc.errno)} (os error {exc.errno})"
    return str(exc)


def execute_operations(ops: List[Operation], opts: Options) -> Tuple[int, bool]:
    """Return (exit_code, attempted_after_plan)."""
    if opts.is_dry:
        for op in ops:
            print_operation(op, opts)
        return 0, False
    for op in ops:
        try:
            maybe_backup(op.source, opts)
            os.rename(op.source, op.target)
            print_operation(op, opts)
        except Exception as e:
            if not opts.silent:
                stderr_write(f"Error: Cannot rename {op.source} -> {op.target}\n{os_error_text(e)}\n")
            return 1, True
    return 0, True


def dump_operations(ops: List[Operation], opts: Options):
    if not opts.should_dump():
        return
    now = datetime.now()
    fname = f"{opts.dump_prefix}{now.strftime('%Y-%m-%d_%H%M%S')}.json"
    data: Dict[str, Any] = {
        "date": now.strftime('%Y-%m-%d %H:%M:%S'),
        "operations": [{"source": op.source, "target": op.target} for op in ops],
    }
    with open(fname, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
}


def validate_generated_operations(ops: List[Operation], opts: Options) -> Optional[int]:
    # Duplicate targets first.
    groups: Dict[str, List[Operation]] = {}
    for op in ops:
        groups.setdefault(op.target, []).append(op)
    dups = {k: v for k, v in groups.items() if len(v) > 1}
    if dups:
        if not opts.silent:
            stderr_write("Error: Files will have the same name\n\n")
            for target in sorted(dups):
                arr = sorted(dups[target], key=lambda o: o.source)
                first = arr[0]
                for other in arr[1:]:
                    stderr_write(f"{first.source}->{target}\n{other.source}->{target}\n\n")
        return 1
    for op in ops:
        try:
            same = os.path.abspath(op.source) == os.path.abspath(op.target)
        except Exception:
            same = op.source == op.target
        if not same and lexists(op.target):
            if not opts.silent:
                stderr_write(f"Error: Conflict with existing path {op.source} -> {op.target}\n")
            return 1
    return None


def run_regex(argv: List[str]) -> int:
    opts, pos, rc = parse_common("regex", argv, "paths")
    if rc != -1:
        return rc
    assert opts is not None and pos is not None
    perr = validate_positionals("regex", pos)
    if perr is not None:
        return perr
    expr, replacement, paths = pos[0], pos[1], pos[2:]
    try:
        regex = re.compile(normalize_regex_pattern(expr))
    except re.error as e:
        # Rust regex's exact diagnostics are crate-specific; keep the public
        # leading error line and include the parser message for users.
        stderr_write("Error: Bad expression provided\n\n")
        if expr == "[":
            stderr_write("regex parse error:\n    [\n    ^\nerror: unclosed character class\n")
        else:
            stderr_write(str(e) + "\n")
        return 1
    print_dry_run(opts)
    ops = build_regex_operations(regex, replacement, paths, opts)
    verr = validate_generated_operations(ops, opts)
    if verr is not None:
        return verr
    code, _ = execute_operations(ops, opts)
    if code == 0:
        dump_operations(ops, opts)
    return code


def run_to_ascii(argv: List[str]) -> int:
    opts, pos, rc = parse_common("to-ascii", argv, "paths")
    if rc != -1:
        return rc
    assert opts is not None and pos is not None
    perr = validate_positionals("to-ascii", pos)
    if perr is not None:
        return perr
    print_dry_run(opts)
    ops = build_ascii_operations(pos, opts)
    verr = validate_generated_operations(ops, opts)
    if verr is not None:
        return verr
    code, _ = execute_operations(ops, opts)
    if code == 0:
        dump_operations(ops, opts)
    return code


def load_dump(path: str, opts: Options) -> Tuple[Optional[List[Operation]], int]:
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except FileNotFoundError:
        if not opts.silent:
            stderr_write(f"Error: Cannot open/read file {path}\n")
        return None, 1
    except OSError:
        if not opts.silent:
            stderr_write(f"Error: Cannot open/read file {path}\n")
        return None, 1
    except Exception:
        if not opts.silent:
            stderr_write(f"Error: Cannot parse JSON file {path}\n")
        return None, 1
    try:
        raw_ops = data["operations"]
        if not isinstance(raw_ops, list):
            raise ValueError
        ops = []
        for item in raw_ops:
            if not isinstance(item, dict):
                raise ValueError
            src = item["source"]
            tgt = item["target"]
            if not isinstance(src, str) or not isinstance(tgt, str):
                raise ValueError
            ops.append(Operation(src, tgt, candidate_is_dir(src), segments_for_ascii(os.path.basename(src), os.path.basename(tgt))))
        return ops, 0
    except Exception:
        if not opts.silent:
            stderr_write(f"Error: Cannot parse JSON file {path}\n")
        return None, 1


def run_from_file(argv: List[str]) -> int:
    opts, pos, rc = parse_common("from-file", argv, "dump")
    if rc != -1:
        return rc
    assert opts is not None and pos is not None
    perr = validate_positionals("from-file", pos)
    if perr is not None:
        return perr
    print_dry_run(opts)
    ops, lrc = load_dump(pos[0], opts)
    if lrc != 0 or ops is None:
        return lrc
    if opts.undo:
        rev = []
        for op in reversed(ops):
            rev.append(Operation(op.target, op.source, candidate_is_dir(op.target), segments_for_ascii(os.path.basename(op.target), os.path.basename(op.source))))
        ops = rev
    code, _ = execute_operations(ops, opts)
    # The original writes a dump for a loaded dump plan even when a forced
    # rename fails part-way through.
    dump_operations(ops, opts)
    return code


def main(argv: List[str]) -> int:
    if not argv:
        stderr_write(TOP_HELP)
        return 2
    first = argv[0]
    if first in ("-h", "--help"):
        stdout_write(TOP_HELP)
        return 0
    if first in ("-V", "--version"):
        stdout_write(VERSION + "\n")
        return 0
    if first == "help":
        rest = argv[1:]
        if not rest:
            stdout_write(TOP_HELP)
            return 0
        if rest[0] == "regex":
            if len(rest) == 1:
                stdout_write(REGEX_HELP); return 0
            return cli_error(f"unrecognized subcommand '{rest[1]}'", "executable regex [OPTIONS] <EXPRESSION> <REPLACEMENT> <PATH(S)>...")
        if rest[0] == "from-file":
            if len(rest) == 1:
                stdout_write(FROM_FILE_HELP); return 0
            return cli_error(f"unrecognized subcommand '{rest[1]}'", "executable from-file [OPTIONS] <DUMPFILE>")
        if rest[0] == "to-ascii":
            if len(rest) == 1:
                stdout_write(TO_ASCII_HELP); return 0
            return cli_error(f"unrecognized subcommand '{rest[1]}'", "executable to-ascii [OPTIONS] <PATH(S)>...")
        return top_unrecognized(rest[0])
    if first == "regex":
        return run_regex(argv[1:])
    if first == "from-file":
        return run_from_file(argv[1:])
    if first == "to-ascii":
        return run_to_ascii(argv[1:])
    return top_unrecognized(first)

if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(0)
